#include <zephyr/kernel.h>
#include <zephyr/kernel_internal.h> // for z_kernel_init
#include <zephyr/init.h>
#include <zephyr/linker/linker-defs.h> // for z_main_thread
#include <zephyr/sys/printk.h>
#include <zephyr/sys/util.h>

#ifdef CONFIG_DEMAND_PAGING
#include <zephyr/mm/paged_ram.h>
#endif

#ifdef CONFIG_EXECUTION_DOMAIN
#include <zephyr/sys/mem_manage.h>
#endif

/*
 * Idle thread
 */
static void idle(void *unused1, void *unused2, void *unused3)
{
	ARG_UNUSED(unused1);
	ARG_UNUSED(unused2);
	ARG_UNUSED(unused3);

	for (;;) {
#ifdef CONFIG_PM
		/*
		 * Call pm subsystem idle enter hook. This function will not return
		 * until the CPU is woken up by an interrupt.
		 */
		pm_system_suspend(K_FOREVER);
#else
		/*
		 * This function is specified by the architecture to put the CPU to
		 * sleep. It can be as simple as a single instruction on some
		 * architectures, and as complex as a function call on others.
		 */
		k_cpu_idle();
#endif
	}
}

extern void main(void);

#ifdef CONFIG_MULTITHREADING
static K_THREAD_STACK_DEFINE(main_stack, CONFIG_MAIN_STACK_SIZE);
static struct k_thread main_thread;
#endif

#ifdef CONFIG_MULTITHREADING
static K_THREAD_STACK_DEFINE(idle_stack, CONFIG_IDLE_STACK_SIZE);
static struct k_thread idle_thread;
#endif

#ifdef CONFIG_THREAD_ANALYZER
void k_call_stacks_analyze(void)
{
	z_thread_analyzer_run();
}
#endif

/**
 *
 * @brief Main kernel initialization routine
 *
 * This routine is responsible for initializing the kernel, creating the main
 * and idle threads, and finally starting the kernel.
 *
 * @return Does not return.
 */
void z_cstart(void)
{
	z_kernel_init();

	z_sys_init_run_level(Z_INIT_LEVEL_PRE_KERNEL_1);
	z_sys_init_run_level(Z_INIT_LEVEL_PRE_KERNEL_2);

	k_sched_lock();

#ifdef CONFIG_MULTITHREADING
	k_thread_create(&main_thread, main_stack, CONFIG_MAIN_STACK_SIZE,
			(k_thread_entry_t)main, NULL, NULL, NULL,
			K_PRIO_PREEMPT(CONFIG_MAIN_THREAD_PRIORITY), 0, K_NO_WAIT);
	k_thread_name_set(&main_thread, "main");

#ifdef CONFIG_USERSPACE
	k_thread_user_mode_enter((k_thread_entry_t)main, NULL, NULL, NULL);
#endif

	k_thread_create(&idle_thread, idle_stack, CONFIG_IDLE_STACK_SIZE,
			idle, NULL, NULL, NULL,
			K_PRIO_PREEMPT(K_LOWEST_APPLICATION_THREAD_PRIO - 1),
			0, K_NO_WAIT);
	k_thread_name_set(&idle_thread, "idle");
#endif

	z_sys_init_run_level(Z_INIT_LEVEL_POST_KERNEL);
	z_sys_init_run_level(Z_INIT_LEVEL_APPLICATION);

#ifdef CONFIG_SMP
	z_sys_init_run_level(Z_INIT_LEVEL_SMP);
#endif

	_kernel.ready = true;

	z_swap_unlocked();

	/* z_swap_unlocked() does not return */
	CODE_UNREACHABLE;
}
